<?php require 'config.php';require_login();$title='Departments';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();if(isset($_POST['delete'])){$pdo->prepare('DELETE FROM departments WHERE id=?')->execute([(int)$_POST['delete']]);flash('Department removed.');}else{$pdo->prepare('INSERT INTO departments(name,description) VALUES(?,?)')->execute([trim($_POST['name']),trim($_POST['description'])]);flash('Department added.');}go('departments.php');}
$rows=$pdo->query('SELECT d.*,COUNT(e.id) total FROM departments d LEFT JOIN employees e ON e.department_id=d.id GROUP BY d.id ORDER BY d.name')->fetchAll();require 'partials/header.php';?>
<div class="pagehead"><div><div class="eyebrow">ORGANIZATION</div><h1>Departments</h1><p class="sub">Create and organize teams within your office.</p></div></div>
<div class="card"><h2>Add department</h2><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><div class="formgrid" style="margin-top:15px"><div class="field"><label>Department name</label><input name="name" required placeholder="e.g. Human Resources"></div><div class="field"><label>Description</label><input name="description" placeholder="Team responsibilities"></div></div><div class="actions"><button class="btn">＋ Add department</button></div></form></div>
<div class="card"><div class="cardhead"><h2>All departments</h2></div><div class="tablewrap"><table><thead><tr><th>Department</th><th>Description</th><th>Employees</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><strong><?=h($r['name'])?></strong></td><td><?=h($r['description'])?></td><td><?=$r['total']?></td><td><form method="post" onsubmit="return confirm('Delete department?')"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><button class="btn danger small" name="delete" value="<?=$r['id']?>">Delete</button></form></td></tr><?php endforeach?><?php if(!$rows):?><tr><td colspan="4" class="empty">No departments created yet.</td></tr><?php endif?></tbody></table></div></div><?php require 'partials/footer.php';?>
